const rows = $input.all().filter((item) => {
  const row = item.json ?? {};

  return (
    !row.skipAll &&
    row.Status === 'READY_TO_SEND' &&
    row.Auto_Send_Allowed === 'TRUE' &&
    String(row.Contact_Email ?? '').includes('@')
  );
});

return rows;

function clean(value){return String(value===undefined||value===null?'':value).trim()}
function warsawStamp(date){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Warsaw',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(date)}
const results=$input.all();
let originals=[];
try{originals=$('Code — Auto-send gate').all().map(item=>item.json||{})}catch(error){originals=[]}
let followDays=10;
try{
  const settings=$('GS — SETTINGS').all().map(item=>item.json||{});
  const row=settings.find(item=>clean(item.Setting)==='FOLLOW_UP_DAYS');
  if(row&&Number.isFinite(Number(row.Value)))followDays=Number(row.Value);
}catch(error){}
const now=new Date();
const stamp=warsawStamp(now);
const dateKey=stamp.slice(0,10).split('-').join('');
const timeKey=stamp.slice(11,19).split(':').join('');
return results.map((item,index)=>{
  const result=item.json||{};
  const source=originals[index]||{};
  const messageId=clean(result.id||result.messageId);
  const threadId=clean(result.threadId);
  const explicitError=clean(result.error?.message||result.error||result.message);
  const deliveryConfirmed=Boolean(messageId) && !result.error;
  const failed=!deliveryConfirmed;
  const error=failed
    ? (explicitError || 'gmail_delivery_not_confirmed: Gmail node is disabled, misconfigured, or returned no message id')
    : '';
  const follow=new Date(now.getTime()+followDays*86400000);
  return{json:{
    Log_ID:'LOG-'+dateKey+'-'+timeKey+'-'+String(index+1).padStart(2,'0'),
    Pitch_ID:clean(source.Pitch_ID),Sent_At:failed?'':stamp,
    Track_ID:clean(source.Track_ID),Track_Name:clean(source.Track_Name),
    Source_ID:clean(source.Source_ID),Source_Name:clean(source.Source_Name),
    Submission_Method:'AUTO_EMAIL',Recipient:clean(source.Contact_Email),
    Subject:clean(source.Pitch_Subject),Message_ID:messageId,Thread_ID:threadId,
    Status:failed?'ERROR':'SENT',Follow_Up_At:failed?'':warsawStamp(follow).slice(0,10),
    Follow_Up_Count:0,Reply_At:'',Reply_Class:'',Reply_Summary:'',Placement_At:'',
    Placement_URL:'',Playlist_Name:clean(source.Source_Name),Estimated_Reach:clean(source.Estimated_Reach),
    Streams_Attributed:'',Monthly_Listeners_Before:'',Monthly_Listeners_After:'',
    Dedupe_Key:clean(source.Dedupe_Key),Error:error,Discord_Reported_At:'',
    Send_Attempt_ID:clean(source._viryaSendAttemptId)
  }};
});

